@@ -10,17 +10,38 @@ template <>
 struct Bitfield<unsigned int> {
   static __device__ __forceinline__
   unsigned int getBitfield(unsigned int val, int pos, int len) {
+#if defined(__HIP_PLATFORM_HCC__)
+    pos &= 0x1f;
+    len &= 0x1f;
+
+    unsigned int m = (1u << len) - 1u;
+    m <<= pos;
+    return val & m;
+#else
     unsigned int ret;
     asm("bfe.u32 %0, %1, %2, %3;" : "=r"(ret) : "r"(val), "r"(pos), "r"(len));
     return ret;
+#endif
   }

   static __device__ __forceinline__
   unsigned int setBitfield(unsigned int val, unsigned int toInsert, int pos, int len) {
+#if defined(__HIP_PLATFORM_HCC__)
+    pos &= 0x1f;
+    len &= 0x1f;
+
+    unsigned int m = (1u << len) - 1u;
+    toInsert &= m;
+    toInsert <<= pos;
+    m <<= pos;
+
+    return (val & ~m) | toInsert;
+#else
     unsigned int ret;
     asm("bfi.b32 %0, %1, %2, %3, %4;" :
         "=r"(ret) : "r"(toInsert), "r"(val), "r"(pos), "r"(len));
     return ret;
+#endif
   }
 };

@@ -28,48 +49,93 @@ template <>
 struct Bitfield<uint64_t> {
   static __device__ __forceinline__
   uint64_t getBitfield(uint64_t val, int pos, int len) {
+#if defined(__HIP_PLATFORM_HCC__)
+    pos &= 0x1f;
+    len &= 0x1f;
+
+    uint64_t m = (1u << len) - 1u;
+    m <<= pos;
+    return val & m;
+#else
     uint64_t ret;
     asm("bfe.u64 %0, %1, %2, %3;" : "=l"(ret) : "l"(val), "r"(pos), "r"(len));
     return ret;
+#endif
   }

   static __device__ __forceinline__
   uint64_t setBitfield(uint64_t val, uint64_t toInsert, int pos, int len) {
+#if defined(__HIP_PLATFORM_HCC__)
+    pos &= 0x1f;
+    len &= 0x1f;
+
+    uint64_t m = (1u << len) - 1u;
+    toInsert &= m;
+    toInsert <<= pos;
+    m <<= pos;
+
+    return (val & ~m) | toInsert;
+#else
     uint64_t ret;
     asm("bfi.b64 %0, %1, %2, %3, %4;" :
         "=l"(ret) : "l"(toInsert), "l"(val), "r"(pos), "r"(len));
     return ret;
+#endif
   }
 };

 __device__ __forceinline__ int getLaneId() {
+#if defined(__HIP_PLATFORM_HCC__)
+  return hc::__lane_id();
+#else
   int laneId;
   asm("mov.s32 %0, %laneid;" : "=r"(laneId) );
   return laneId;
+#endif
 }

 __device__ __forceinline__ unsigned getLaneMaskLt() {
+#if defined(__HIP_PLATFORM_HCC__)
+  std::uint64_t m = (1ull << getLaneId()) - 1ull;
+  return m;
+#else
   unsigned mask;
   asm("mov.u32 %0, %%lanemask_lt;" : "=r"(mask));
   return mask;
+#endif
 }

 __device__ __forceinline__ unsigned getLaneMaskLe() {
+#if defined(__HIP_PLATFORM_HCC__)
+  std::uint64_t m = (1ull << (getLaneId() + 1ull)) - 1ull;
+  return m;
+#else
   unsigned mask;
   asm("mov.u32 %0, %%lanemask_le;" : "=r"(mask));
   return mask;
+#endif
 }

 __device__ __forceinline__ unsigned getLaneMaskGt() {
+#if defined(__HIP_PLATFORM_HCC__)
+  std::uint64_t m = getLaneMaskLe();
+  return m ? ~m : m;
+#else
   unsigned mask;
   asm("mov.u32 %0, %%lanemask_gt;" : "=r"(mask));
   return mask;
+#endif
 }

 __device__ __forceinline__ unsigned getLaneMaskGe() {
+#if defined(__HIP_PLATFORM_HCC__)
+  std::uint64_t m = getLaneMaskLt();
+  return ~m;
+#else
   unsigned mask;
   asm("mov.u32 %0, %%lanemask_ge;" : "=r"(mask));
   return mask;
+#endif
 }


